import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import standaloneCode from 'ajv/dist/standalone/index.js';
import { BUNDLE_FORMAT_VERSION } from '../bundle-format.mjs';
import { loadSchemas } from './load-schemas.mjs';
import { resolveSchemaPackage } from './schema-package.mjs';

const require = createRequire(import.meta.url);
const AJV_VERSION = require('ajv/package.json').version;
const STANDALONE_OPTIONS = { code: { source: true, esm: true, optimize: true } };

// ajv runtime helpers the standalone code may require, copied into validators.mjs so schema packages
// need no dependencies. Only self-contained functions belong here: their source is taken from ajv as is.
const INLINABLE_HELPERS = {
  'ajv/dist/runtime/ucs2length': () => require('ajv/dist/runtime/ucs2length').default,
};

const VALIDATE_FUNCTION = '((value: unknown) => boolean) & { errors?: unknown[] | null }';

export function compileBundle(schemas, { from } = {}) {
  const pkg = resolveSchemaPackage(schemas, { from });
  const { ajv, entries } = loadSchemas(path.join(pkg.root, 'schemas'), STANDALONE_OPTIONS);
  const { exportedIds, namedEntries } = nameValidators(ajv, entries);
  const names = Object.keys(exportedIds);
  return {
    bundle: {
      formatVersion: BUNDLE_FORMAT_VERSION,
      package: { name: pkg.name, version: pkg.version },
      cobblemon: pkg.cobblemon,
      compiler: { ajv: AJV_VERSION },
      entries: namedEntries,
    },
    validators: inlineRuntimeHelpers(standaloneCode(ajv, exportedIds)),
    declarations: declarationsFor(names),
  };
}

export function buildSchemaPackage(schemas, { from } = {}) {
  const pkg = resolveSchemaPackage(schemas, { from });
  const { bundle, validators, declarations } = compileBundle(pkg);
  const dist = path.join(pkg.root, 'dist');
  const files = {
    'bundle.json': JSON.stringify(bundle),
    'validators.mjs': validators,
    'validators.d.mts': declarations,
  };
  fs.mkdirSync(dist, { recursive: true });
  for (const [name, content] of Object.entries(files)) fs.writeFileSync(path.join(dist, name), content);
  return { package: pkg, dist, validatorCount: bundle.entries.filter((entry) => entry.validator).length };
}

function nameValidators(ajv, entries) {
  const exportedIds = {};
  const namedEntries = entries.map((entry, i) => {
    if (!entry.id || !ajv.getSchema(entry.id)) return entry;
    const name = `v${i}`;
    exportedIds[name] = entry.id;
    return { ...entry, validator: name };
  });
  return { exportedIds, namedEntries };
}

function inlineRuntimeHelpers(code) {
  const inlined = code.replace(/const (\w+) = require\("([^"]+)"\)(\.default)?;/g, (_, name, module) => {
    const helper = INLINABLE_HELPERS[module];
    if (!helper) {
      throw new Error(
        `The standalone validators need ${module}, which the build doesn't inline. If it's self-contained, add it ` +
          'to INLINABLE_HELPERS in compile-bundle.mjs; otherwise the schema packages need ajv as a dependency.',
      );
    }
    return `const ${name} = ${helper().toString()};`;
  });
  if (/\brequire\(/.test(inlined)) throw new Error('Standalone validator code still contains require() calls.');
  return inlined;
}

function declarationsFor(names) {
  const lines = names.map((name) => `export declare const ${name}: ${VALIDATE_FUNCTION};`);
  return `// Generated by @cobbled-creators/cobblemon-validator. dist/bundle.json maps each schema to its validator.\n${lines.join('\n')}\n`;
}
